using ShipmentTracker.Client.Models;
using ShipmentTracker.Client.Services;

namespace ShipmentTracker.Services;

/// <summary>
/// Server-side in-memory shipment service. Replace with EF Core for production.
/// </summary>
public class ShipmentServerService : IShipmentService
{
    private static readonly List<Shipment> Shipments = new()
    {
        new() { Id = 1, TrackingNumber = "TRK-1001", Description = "Electronics Bundle", Origin = "Los Angeles, CA", Destination = "New York, NY", Status = ShipmentStatus.InTransit, ShippedDate = DateTime.UtcNow.AddDays(-3), EstimatedDelivery = DateTime.UtcNow.AddDays(2), CustomerEmail = "alice@example.com" },
        new() { Id = 2, TrackingNumber = "TRK-1002", Description = "Office Supplies", Origin = "Chicago, IL", Destination = "Miami, FL", Status = ShipmentStatus.Pending, ShippedDate = DateTime.UtcNow.AddDays(-1), EstimatedDelivery = DateTime.UtcNow.AddDays(4), CustomerEmail = "bob@example.com" },
        new() { Id = 3, TrackingNumber = "TRK-1003", Description = "Medical Equipment", Origin = "Seattle, WA", Destination = "Houston, TX", Status = ShipmentStatus.OutForDelivery, ShippedDate = DateTime.UtcNow.AddDays(-5), EstimatedDelivery = DateTime.UtcNow, CustomerEmail = "carol@example.com" },
        new() { Id = 4, TrackingNumber = "TRK-1004", Description = "Furniture Set", Origin = "Denver, CO", Destination = "Phoenix, AZ", Status = ShipmentStatus.Delivered, ShippedDate = DateTime.UtcNow.AddDays(-7), EstimatedDelivery = DateTime.UtcNow.AddDays(-1), CustomerEmail = "dave@example.com" },
        new() { Id = 5, TrackingNumber = "TRK-1005", Description = "Auto Parts", Origin = "Detroit, MI", Destination = "Atlanta, GA", Status = ShipmentStatus.Delayed, ShippedDate = DateTime.UtcNow.AddDays(-4), EstimatedDelivery = DateTime.UtcNow.AddDays(3), CustomerEmail = "eve@example.com" },
        new() { Id = 6, TrackingNumber = "TRK-1006", Description = "Clothing Shipment", Origin = "Portland, OR", Destination = "Boston, MA", Status = ShipmentStatus.InTransit, ShippedDate = DateTime.UtcNow.AddDays(-2), EstimatedDelivery = DateTime.UtcNow.AddDays(3), CustomerEmail = "frank@example.com" },
    };

    private static int _nextId = 7;

    public Task<List<Shipment>> GetShipmentsAsync(ShipmentStatus? statusFilter = null)
    {
        var result = statusFilter.HasValue
            ? Shipments.Where(s => s.Status == statusFilter.Value).ToList()
            : Shipments.ToList();

        return Task.FromResult(result);
    }

    public Task<Shipment?> GetShipmentByTrackingNumberAsync(string trackingNumber)
    {
        var shipment = Shipments.FirstOrDefault(
            s => s.TrackingNumber.Equals(trackingNumber, StringComparison.OrdinalIgnoreCase));
        return Task.FromResult(shipment);
    }

    public Task UpdateShipmentStatusAsync(int id, ShipmentStatus newStatus)
    {
        var shipment = Shipments.FirstOrDefault(s => s.Id == id);
        if (shipment is not null)
            shipment.Status = newStatus;
        return Task.CompletedTask;
    }
}

